#include <stdlib.h>
    typedef struct { char* path; char* text; } LmDoc;
    static LmDoc* lm_docs;
    static int32_t lm_doc_n, lm_doc_cap;

    static char* lm_doc_copy(const char* s) {
        size_t n = strlen(s);
        char* p = (char*)malloc(n + 1);
        if (!p) rt_panic("out of memory for the editor's documents", 0);
        memcpy(p, s, n + 1);
        return p;
    }
    static int32_t lm_doc_find(const char* path) {
        for (int32_t i = 0; i < lm_doc_n; i++) if (strcmp(lm_docs[i].path, path) == 0) return i;
        return -1;
    }
    static void lm_doc_set(const char* path, const char* text) {
        int32_t i = lm_doc_find(path);
        if (i >= 0) {
            free(lm_docs[i].text);
            lm_docs[i].text = lm_doc_copy(text);
            return;
        }
        if (lm_doc_n == lm_doc_cap) {
            lm_doc_cap = lm_doc_cap ? lm_doc_cap * 2 : 16;
            lm_docs = (LmDoc*)realloc(lm_docs, sizeof(LmDoc) * (size_t)lm_doc_cap);
            if (!lm_docs) rt_panic("out of memory for the editor's documents", 0);
        }
        lm_docs[lm_doc_n].path = lm_doc_copy(path);
        lm_docs[lm_doc_n].text = lm_doc_copy(text);
        lm_doc_n++;
    }
    static void lm_doc_remove(const char* path) {
        int32_t i = lm_doc_find(path);
        if (i < 0) return;
        free(lm_docs[i].path);
        free(lm_docs[i].text);
        lm_docs[i] = lm_docs[--lm_doc_n];
    }
    static bool lm_doc_has(const char* path) { return lm_doc_find(path) >= 0; }
    static const char* lm_doc_text(const char* path) { int32_t i = lm_doc_find(path); return i >= 0 ? lm_docs[i].text : ""; }
    static int32_t lm_doc_count(void) { return lm_doc_n; }
    static const char* lm_doc_path(int32_t i) { return i >= 0 && i < lm_doc_n ? lm_docs[i].path : ""; }


/* ---- c_code ---------------------------------------------------------------- */
#ifndef _WIN32
    #include <unistd.h>
    #include <poll.h>
    #include <sys/types.h>
    #include <sys/wait.h>
    #endif
    #include <stdlib.h>

    #ifndef _WIN32
    static int lm_lsp_pipe[2] = { -1, -1 };     /* (Windows has no fork: the worker is a process) */
    #endif

    /* fork with a pipe from the child: 0 in the child, its pid in the server, -1 if it cannot */
    static int32_t lm_lsp_fork(void) {
    #ifdef _WIN32
        return -1;
    #else
        fflush(stdout);
        fflush(stderr);
        if (pipe(lm_lsp_pipe) != 0) return -1;
        pid_t p = fork();
        if (p < 0) {
            close(lm_lsp_pipe[0]);
            close(lm_lsp_pipe[1]);
            return -1;
        }
        if (p == 0) {
            close(lm_lsp_pipe[0]);
            dup2(2, 1);                  /* stdout is the editor's: nothing the analysis prints goes there */
            alarm(60);                   /* an analysis that never ends must not stay forever */
            return 0;
        }
        close(lm_lsp_pipe[1]);
        return (int32_t)p;
    #endif
    }

    /* in the child: writes the answer and ends */
    static void lm_lsp_send(const char* text, int32_t len) {
    #ifndef _WIN32
        size_t done = 0;
        while (done < (size_t)len) {
            ssize_t k = write(lm_lsp_pipe[1], text + done, (size_t)len - done);
            if (k <= 0) break;
            done += (size_t)k;
        }
        close(lm_lsp_pipe[1]);
        _exit(0);
    #endif
    }

    /* in the child: ends without answering, with a code for the one waiting */
    static void lm_lsp_quit(int32_t code) {
    #ifndef _WIN32
        _exit(code);
    #endif
    }

    /* in the server: everything the child wrote ("" if it ended without answering) */
    static const char* lm_lsp_receive(RtMem* m, int32_t pid) {
        RtSb sb = rt_sb_mem(m, 0);
        rt_sb_add(&sb, "", 0);
    #ifndef _WIN32
        char buf[65536];
        for (;;) {
            ssize_t k = read(lm_lsp_pipe[0], buf, sizeof buf);
            if (k < 0 && errno == EINTR) continue;
            if (k <= 0) break;
            rt_sb_add(&sb, buf, (int32_t)k);
        }
        close(lm_lsp_pipe[0]);
        int status = 0;
        while (waitpid((pid_t)pid, &status, 0) < 0 && errno == EINTR) {}
    #endif
        return sb.buf;
    }

    /*
     * In the child: one more process tries first (the program of the project, which may not reach the
     * file). 0: this is that process; 1: it answered, so the child ends; 2: it could not.
     */
    static int32_t lm_lsp_attempt(void) {
    #ifdef _WIN32
        return 2;
    #else
        fflush(stderr);
        pid_t p = fork();
        if (p < 0) return 2;
        if (p == 0) return 0;
        int status = 0;
        while (waitpid(p, &status, 0) < 0 && errno == EINTR) {}
        return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : 2;
    #endif
    }

    /* whether a message arrives on stdin within ms milliseconds */
    static bool lm_lsp_waiting(int32_t ms) {
    #ifdef _WIN32
        return false;
    #else
        struct pollfd p;
        p.fd = 0;
        p.events = POLLIN;
        p.revents = 0;
        return poll(&p, 1, ms) > 0;
    #endif
    }

    /* stdin without a buffer of its own, so poll() sees every byte that has not been read */
    static void lm_lsp_unbuffered(void) { setvbuf(stdin, NULL, _IONBF, 0); }

    /* the file whose errors are still to be published */
    static char* lm_lsp_pending;
    static void lm_lsp_set_pending(const char* path) {
        free(lm_lsp_pending);
        lm_lsp_pending = NULL;
        if (path[0]) {
            size_t n = strlen(path);
            lm_lsp_pending = (char*)malloc(n + 1);
            if (lm_lsp_pending) memcpy(lm_lsp_pending, path, n + 1);
        }
    }
    static const char* lm_lsp_get_pending(void) { return lm_lsp_pending ? lm_lsp_pending : ""; }

    #ifdef _WIN32
    #include <process.h>
    static int32_t lm_lsp_pid(void) { return (int32_t)_getpid(); }
    #else
    static int32_t lm_lsp_pid(void) { return (int32_t)getpid(); }
    #endif


/* ---- c_code ---------------------------------------------------------------- */
#include <stdlib.h>
    #include <string.h>
    #ifdef _WIN32
    #include <windows.h>
    #include <io.h>
    #else
    #include <unistd.h>
    #include <poll.h>
    #include <signal.h>
    #include <sys/types.h>
    #include <sys/wait.h>
    #endif

    /* two input streams: 0 the editor (stdin), 1 the backend (lldb-dap's stdout) */
    typedef struct { char* buf; size_t len, cap; bool eof; } LmDapIn;
    static LmDapIn lm_dap_in[2];
    #ifdef _WIN32
    static HANDLE lm_dap_child_in, lm_dap_child_out, lm_dap_proc;
    #else
    static int lm_dap_child_in = -1, lm_dap_child_out = -1;
    static pid_t lm_dap_pid = -1;
    #endif

    /* starts the backend with pipes for its input and output; false if it cannot */
    static bool lm_dap_spawn(const char* path) {
    #ifdef _WIN32
        SECURITY_ATTRIBUTES sa = { sizeof sa, NULL, TRUE };
        HANDLE inR, inW, outR, outW;
        if (!CreatePipe(&inR, &inW, &sa, 0) || !CreatePipe(&outR, &outW, &sa, 0)) return false;
        SetHandleInformation(inW, HANDLE_FLAG_INHERIT, 0);
        SetHandleInformation(outR, HANDLE_FLAG_INHERIT, 0);
        STARTUPINFOA si; PROCESS_INFORMATION pi;
        memset(&si, 0, sizeof si); memset(&pi, 0, sizeof pi);
        si.cb = sizeof si;
        si.dwFlags = STARTF_USESTDHANDLES;
        si.hStdInput = inR; si.hStdOutput = outW; si.hStdError = GetStdHandle(STD_ERROR_HANDLE);
        char cmd[4096];
        snprintf(cmd, sizeof cmd, "\"%s\"", path);
        if (!CreateProcessA(NULL, cmd, NULL, NULL, TRUE, CREATE_NO_WINDOW, NULL, NULL, &si, &pi)) return false;
        CloseHandle(inR); CloseHandle(outW); CloseHandle(pi.hThread);
        lm_dap_child_in = inW; lm_dap_child_out = outR; lm_dap_proc = pi.hProcess;
        _setmode(_fileno(stdin), 0x8000); _setmode(_fileno(stdout), 0x8000);   /* _O_BINARY */
        return true;
    #else
        int in[2], out[2];
        if (pipe(in) != 0 || pipe(out) != 0) return false;
        pid_t p = fork();
        if (p < 0) return false;
        if (p == 0) {
            dup2(in[0], 0);
            dup2(out[1], 1);
            close(in[0]); close(in[1]); close(out[0]); close(out[1]);
            execlp(path, path, (char*)NULL);
            _exit(127);
        }
        close(in[0]); close(out[1]);
        lm_dap_child_in = in[1]; lm_dap_child_out = out[0]; lm_dap_pid = p;
        signal(SIGPIPE, SIG_IGN);
        return true;
    #endif
    }

    static void lm_dap_kill(void) {
    #ifdef _WIN32
        if (lm_dap_proc) TerminateProcess(lm_dap_proc, 0);
    #else
        if (lm_dap_pid > 0) { kill(lm_dap_pid, SIGTERM); waitpid(lm_dap_pid, NULL, 0); lm_dap_pid = -1; }
    #endif
    }

    static void lm_dap_append(int which, const char* data, size_t n) {
        LmDapIn* in = &lm_dap_in[which];
        if (in->len + n + 1 > in->cap) {
            in->cap = (in->len + n + 1) * 2;
            in->buf = (char*)realloc(in->buf, in->cap);
            if (!in->buf) rt_panic("out of memory (larimar dap)", 0);
        }
        memcpy(in->buf + in->len, data, n);
        in->len += n;
        in->buf[in->len] = 0;
    }

    /* reads what is ready on either stream, waiting up to ms milliseconds (-1: until something comes) */
    static void lm_dap_fill(int32_t ms) {
        char tmp[65536];
    #ifdef _WIN32
        HANDLE hs[2] = { GetStdHandle(STD_INPUT_HANDLE), lm_dap_child_out };
        DWORD waited = 0;
        for (;;) {
            bool got = false;
            for (int i = 0; i < 2; i++) {
                if (lm_dap_in[i].eof) continue;
                DWORD avail = 0;
                if (!PeekNamedPipe(hs[i], NULL, 0, NULL, &avail, NULL)) { lm_dap_in[i].eof = true; got = true; continue; }
                if (avail > 0) {
                    DWORD n = 0;
                    if (ReadFile(hs[i], tmp, avail < sizeof tmp ? avail : sizeof tmp, &n, NULL) && n > 0) lm_dap_append(i, tmp, n);
                    else lm_dap_in[i].eof = true;
                    got = true;
                }
            }
            if (got || (ms >= 0 && (int32_t)waited >= ms) || (lm_dap_in[0].eof && lm_dap_in[1].eof)) return;
            Sleep(2);
            waited += 2;
        }
    #else
        struct pollfd p[2];
        p[0].fd = lm_dap_in[0].eof ? -1 : 0;
        p[1].fd = lm_dap_in[1].eof ? -1 : lm_dap_child_out;
        p[0].events = p[1].events = POLLIN;
        p[0].revents = p[1].revents = 0;
        if (poll(p, 2, ms) <= 0) return;
        for (int i = 0; i < 2; i++) {
            if (!(p[i].revents & (POLLIN | POLLHUP | POLLERR))) continue;
            ssize_t n = read(p[i].fd, tmp, sizeof tmp);
            if (n > 0) lm_dap_append(i, tmp, (size_t)n); else lm_dap_in[i].eof = true;
        }
    #endif
    }

    static bool lm_dap_eof(int32_t which) { return lm_dap_in[which].eof && lm_dap_in[which].len == 0; }

    /* the body of the next complete message of a stream, or "" (and lm_dap_took() false) */
    static bool lm_dap_got;
    static const char* lm_dap_take(RtMem* m, int32_t which) {
        LmDapIn* in = &lm_dap_in[which];
        lm_dap_got = false;
        if (in->len == 0) return "";
        char* end = strstr(in->buf, "\r\n\r\n");
        if (!end) return "";
        long length = -1;
        for (char* h = in->buf; h < end; ) {
            char* eol = strstr(h, "\r\n");
            if (!eol || eol > end) eol = end;
            if (eol - h > 15 && (strncmp(h, "Content-Length:", 15) == 0 || strncmp(h, "content-length:", 15) == 0)) length = atol(h + 15);
            h = eol + 2;
        }
        size_t head = (size_t)(end - in->buf) + 4;
        if (length < 0) {                          /* not a message: drop the header */
            memmove(in->buf, in->buf + head, in->len - head + 1);
            in->len -= head;
            return "";
        }
        if (in->len < head + (size_t)length) return "";
        char* body = (char*)rt_mem_alloc(m, (size_t)length + 1, 0);
        memcpy(body, in->buf + head, (size_t)length);
        body[length] = 0;
        memmove(in->buf, in->buf + head + length, in->len - head - (size_t)length + 1);
        in->len -= head + (size_t)length;
        lm_dap_got = true;
        return body;
    }
    static bool lm_dap_took(void) { return lm_dap_got; }

    /* writes one message: 0 to the editor, 1 to the backend */
    static void lm_dap_write(int32_t which, const char* body, int32_t len) {
        char head[64];
        int hn = snprintf(head, sizeof head, "Content-Length: %d\r\n\r\n", len);
        if (which == 0) {
            fwrite(head, 1, (size_t)hn, stdout);
            fwrite(body, 1, (size_t)len, stdout);
            fflush(stdout);
            return;
        }
    #ifdef _WIN32
        DWORD n;
        WriteFile(lm_dap_child_in, head, (DWORD)hn, &n, NULL);
        WriteFile(lm_dap_child_in, body, (DWORD)len, &n, NULL);
    #else
        size_t done = 0;
        while (done < (size_t)hn) { ssize_t k = write(lm_dap_child_in, head + done, (size_t)hn - done); if (k <= 0) return; done += (size_t)k; }
        done = 0;
        while (done < (size_t)len) { ssize_t k = write(lm_dap_child_in, body + done, (size_t)len - done); if (k <= 0) return; done += (size_t)k; }
    #endif
    }

    /* handles the editor gets for variables: what each one shows (freed at every stop) */
    typedef struct { int32_t kind, frame, ref; char* expr; char* type; } LmDapHandle;
    static LmDapHandle* lm_dap_h;
    static int32_t lm_dap_hn, lm_dap_hcap;
    static char* lm_dap_dup(const char* s) { size_t n = strlen(s); char* p = (char*)malloc(n + 1); if (p) memcpy(p, s, n + 1); return p; }
    static int32_t lm_dap_handle(int32_t kind, int32_t frame, int32_t ref, const char* expr, const char* type) {
        if (lm_dap_hn == lm_dap_hcap) {
            lm_dap_hcap = lm_dap_hcap ? lm_dap_hcap * 2 : 256;
            lm_dap_h = (LmDapHandle*)realloc(lm_dap_h, sizeof(LmDapHandle) * (size_t)lm_dap_hcap);
            if (!lm_dap_h) rt_panic("out of memory (larimar dap)", 0);
        }
        LmDapHandle* h = &lm_dap_h[lm_dap_hn++];
        h->kind = kind; h->frame = frame; h->ref = ref; h->expr = lm_dap_dup(expr); h->type = lm_dap_dup(type);
        return lm_dap_hn;                          /* from 1: 0 means "no children" */
    }
    static void lm_dap_clear(void) {
        for (int32_t i = 0; i < lm_dap_hn; i++) { free(lm_dap_h[i].expr); free(lm_dap_h[i].type); }
        lm_dap_hn = 0;
    }
    static bool lm_dap_valid(int32_t id) { return id >= 1 && id <= lm_dap_hn; }
    static int32_t lm_dap_h_kind(int32_t id) { return lm_dap_valid(id) ? lm_dap_h[id - 1].kind : 0; }
    static int32_t lm_dap_h_frame(int32_t id) { return lm_dap_valid(id) ? lm_dap_h[id - 1].frame : 0; }
    static int32_t lm_dap_h_ref(int32_t id) { return lm_dap_valid(id) ? lm_dap_h[id - 1].ref : 0; }
    static const char* lm_dap_h_expr(int32_t id) { return lm_dap_valid(id) ? lm_dap_h[id - 1].expr : ""; }
    static const char* lm_dap_h_type(int32_t id) { return lm_dap_valid(id) ? lm_dap_h[id - 1].type : ""; }


/* ---- c_code ---------------------------------------------------------------- */
/* The shortest decimal text that gives the same double back. */
    static const char* gen_double_text(double d) {
        char* buf = (char*)rt_mem_alloc(&rt_default_mem, 40, 0);
        for (int p = 1; p <= 17; p++) {
            snprintf(buf, 40, "%.*g", p, d);
            if (strtod(buf, NULL) == d) break;
        }
        if (!strpbrk(buf, ".eEni")) strcat(buf, ".0");
        return buf;
    }


/* ---- c_code (std) ---------------------------------------------------------- */
#include <string.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <errno.h>
#if !defined(_WIN32)
#include <poll.h>
#include <fcntl.h>
#endif

typedef struct LmProcess {
    char** args;            /* program and arguments, NULL at the end */
    int argCount;
    char** env;             /* "NAME=value" added to this program's environment */
    int envCount;
    int quiet;
    int mergeErrors;        /* its error output goes into its output */
    int shareConsole;       /* it uses this program's input, output and error output */
    int started, exited, code;
#if defined(_WIN32)
    HANDLE process, input, output;
#else
    pid_t pid;
    int input, output;
#endif
} LmProcess;

static char* lm_proc_copy(const char* s) {
    size_t n = strlen(s);
    char* c = (char*)malloc(n + 1);
    if (!c) rt_panic("out of memory starting a process", 0);
    memcpy(c, s, n + 1);
    return c;
}

static void lm_proc_push(char*** list, int* count, const char* s) {
    char** grown = (char**)realloc(*list, sizeof(char*) * (size_t)(*count + 2));
    if (!grown) rt_panic("out of memory starting a process", 0);
    grown[*count] = lm_proc_copy(s);
    grown[*count + 1] = NULL;
    *list = grown;
    *count += 1;
}

static LmProcess* lm_proc_new(const char* program, int quiet, int mergeErrors, int shareConsole) {
    LmProcess* p = (LmProcess*)calloc(1, sizeof(LmProcess));
    if (!p) rt_panic("out of memory starting a process", 0);
    p->quiet = quiet;
    p->mergeErrors = mergeErrors;
    p->shareConsole = shareConsole;
#if defined(_WIN32)
    p->process = p->input = p->output = NULL;
#else
    p->input = p->output = -1;
#endif
    lm_proc_push(&p->args, &p->argCount, program);
    return p;
}
static void lm_proc_arg(LmProcess* p, const char* a) { lm_proc_push(&p->args, &p->argCount, a); }
static void lm_proc_env(LmProcess* p, const char* e) { lm_proc_push(&p->env, &p->envCount, e); }

/* Milliseconds from some fixed moment: for the time a read may still wait. */
static long long lm_proc_now(void) {
#if defined(_WIN32)
    return (long long)GetTickCount64();
#else
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return (long long)t.tv_sec * 1000 + t.tv_nsec / 1000000;
#endif
}

static void lm_proc_close_input(LmProcess* p) {
#if defined(_WIN32)
    if (p->input) { CloseHandle(p->input); p->input = NULL; }
#else
    if (p->input >= 0) { close(p->input); p->input = -1; }
#endif
}

#if defined(_WIN32)
/* One argument for CreateProcess's command line, quoted the way the C runtime reads it back. */
static void lm_proc_quote(char** line, size_t* len, size_t* cap, const char* a) {
    size_t need = *len + strlen(a) * 2 + 4;
    if (need > *cap) {
        *cap = need * 2;
        *line = (char*)realloc(*line, *cap);
        if (!*line) rt_panic("out of memory starting a process", 0);
    }
    char* o = *line + *len;
    if (*len > 0) *o++ = ' ';
    *o++ = '"';
    for (const char* c = a; *c; c++) {
        size_t slashes = 0;
        while (c[slashes] == '\\') slashes++;
        if (c[slashes] == '"' || c[slashes] == 0) {
            for (size_t i = 0; i < slashes * 2; i++) *o++ = '\\';    /* before a quote, or the end: doubled */
            c += slashes;
            if (*c == 0) break;
            *o++ = '\\';
            *o++ = '"';
        } else {
            for (size_t i = 0; i < slashes; i++) *o++ = '\\';
            c += slashes;
            *o++ = *c;
        }
    }
    *o++ = '"';
    *o = 0;
    *len = (size_t)(o - *line);
}
#endif

/* Starts it: 0, or the error code of the system (the program was not found, cannot run...). */
static int lm_proc_start(LmProcess* p) {
#if defined(_WIN32)
    SECURITY_ATTRIBUTES sa;
    HANDLE inRead, inWrite, outRead, outWrite, errTarget = NULL;
    STARTUPINFOA si;
    PROCESS_INFORMATION pi;
    char* line = NULL;
    size_t len = 0, cap = 0;
    char* block = NULL;
    BOOL ok;
    sa.nLength = sizeof sa;
    sa.lpSecurityDescriptor = NULL;
    sa.bInheritHandle = TRUE;
    if (!CreatePipe(&inRead, &inWrite, &sa, 0)) return (int)GetLastError();
    if (!CreatePipe(&outRead, &outWrite, &sa, 0)) { CloseHandle(inRead); CloseHandle(inWrite); return (int)GetLastError(); }
    SetHandleInformation(inWrite, HANDLE_FLAG_INHERIT, 0);          /* this side stays here */
    SetHandleInformation(outRead, HANDLE_FLAG_INHERIT, 0);
    if (p->quiet) errTarget = CreateFileA("NUL", GENERIC_WRITE, FILE_SHARE_WRITE, &sa, OPEN_EXISTING, 0, NULL);
    for (int i = 0; i < p->argCount; i++) lm_proc_quote(&line, &len, &cap, p->args[i]);
    if (p->envCount > 0) {                                          /* this program's environment, and the additions */
        char* current = GetEnvironmentStringsA();
        size_t used = 0, size = 0;
        const char* e = current;
        while (*e) { size_t n = strlen(e) + 1; used += n; e += n; }
        size = used + 1;
        for (int i = 0; i < p->envCount; i++) size += strlen(p->env[i]) + 1;
        block = (char*)malloc(size);
        if (!block) rt_panic("out of memory starting a process", 0);
        memcpy(block, current, used);
        for (int i = 0; i < p->envCount; i++) {
            size_t n = strlen(p->env[i]) + 1;
            memcpy(block + used, p->env[i], n);
            used += n;
        }
        block[used] = 0;
        FreeEnvironmentStringsA(current);
    }
    memset(&si, 0, sizeof si);
    si.cb = sizeof si;
    si.dwFlags = STARTF_USESTDHANDLES;
    si.hStdInput = p->shareConsole ? GetStdHandle(STD_INPUT_HANDLE) : inRead;
    si.hStdOutput = p->shareConsole ? GetStdHandle(STD_OUTPUT_HANDLE) : outWrite;
    si.hStdError = p->mergeErrors && !p->shareConsole ? outWrite : p->quiet && errTarget != INVALID_HANDLE_VALUE ? errTarget : GetStdHandle(STD_ERROR_HANDLE);
    ok = CreateProcessA(NULL, line, NULL, NULL, TRUE, 0, block, NULL, &si, &pi);
    int error = ok ? 0 : (int)GetLastError();
    free(line);
    free(block);
    CloseHandle(inRead);
    CloseHandle(outWrite);
    if (errTarget && errTarget != INVALID_HANDLE_VALUE) CloseHandle(errTarget);
    if (!ok) { CloseHandle(inWrite); CloseHandle(outRead); return error; }
    CloseHandle(pi.hThread);
    p->process = pi.hProcess;
    p->input = inWrite;
    p->output = outRead;
    p->started = 1;
    return 0;
#else
    int in[2], out[2], report[2];
    if (pipe(in) != 0) return errno;
    if (pipe(out) != 0) { close(in[0]); close(in[1]); return errno; }
    if (pipe(report) != 0) { close(in[0]); close(in[1]); close(out[0]); close(out[1]); return errno; }
    fcntl(report[1], F_SETFD, FD_CLOEXEC);          /* closed by exec: an empty report means it started */
    signal(SIGPIPE, SIG_IGN);                       /* writing to one that ended is an error, not the end of this one */
    fflush(stdout);
    fflush(stderr);
    pid_t pid = fork();
    if (pid < 0) {
        int e = errno;
        close(in[0]); close(in[1]); close(out[0]); close(out[1]); close(report[0]); close(report[1]);
        return e;
    }
    if (pid == 0) {                                 /* the new process */
        if (!p->shareConsole) {
            dup2(in[0], 0);
            dup2(out[1], 1);
        }
        if (p->mergeErrors && !p->shareConsole) {
            dup2(out[1], 2);
        } else if (p->quiet) {
            int null = open("/dev/null", O_WRONLY);
            if (null >= 0) { dup2(null, 2); close(null); }
        }
        close(in[0]); close(in[1]); close(out[0]); close(out[1]); close(report[0]);
        for (int i = 0; i < p->envCount; i++) putenv(p->env[i]);
        execvp(p->args[0], p->args);
        int e = errno;
        if (write(report[1], &e, sizeof e) < 0) { }
        _exit(127);
    }
    close(in[0]);
    close(out[1]);
    close(report[1]);
    int e = 0;
    ssize_t n;
    do { n = read(report[0], &e, sizeof e); } while (n < 0 && errno == EINTR);
    close(report[0]);
    if (n > 0) {                                    /* exec failed: the child already ended */
        int status;
        waitpid(pid, &status, 0);
        close(in[1]);
        close(out[0]);
        return e != 0 ? e : ENOENT;
    }
    p->pid = pid;
    p->input = in[1];
    p->output = out[0];
    p->started = 1;
    return 0;
#endif
}

/* What a start error means, in English. */
static const char* lm_proc_error_text(int code) {
#if defined(_WIN32)
    if (code == ERROR_FILE_NOT_FOUND || code == ERROR_PATH_NOT_FOUND) return "not found";
    if (code == ERROR_ACCESS_DENIED) return "permission denied";
    return "cannot start it";
#else
    if (code == ENOENT) return "not found";
    if (code == EACCES) return "permission denied";
    return strerror(code);
#endif
}

/* Writes all the bytes: 1, or 0 when it stopped reading (it ended, or closed its input). */
static int lm_proc_write(LmProcess* p, const char* bytes, long long count) {
#if defined(_WIN32)
    while (count > 0) {
        DWORD wrote = 0;
        if (!p->input || !WriteFile(p->input, bytes, (DWORD)count, &wrote, NULL)) return 0;
        bytes += wrote;
        count -= wrote;
    }
    return 1;
#else
    while (count > 0) {
        if (p->input < 0) return 0;
        ssize_t n = write(p->input, bytes, (size_t)count);
        if (n < 0 && errno == EINTR) continue;
        if (n <= 0) return 0;
        bytes += n;
        count -= n;
    }
    return 1;
#endif
}

/* Reads what is there, waiting up to `ms`: the count, 0 when nothing came in time, -1 at its end. */
static int lm_proc_read(LmProcess* p, char* into, int size, int ms) {
#if defined(_WIN32)
    long long until = lm_proc_now() + ms;
    for (;;) {
        DWORD ready = 0, got = 0;
        if (!PeekNamedPipe(p->output, NULL, 0, NULL, &ready, NULL)) return -1;     /* it ended */
        if (ready > 0) {
            if (!ReadFile(p->output, into, ready < (DWORD)size ? ready : (DWORD)size, &got, NULL)) return -1;
            return (int)got;
        }
        if (lm_proc_now() >= until) return 0;
        Sleep(5);
    }
#else
    struct pollfd w;
    w.fd = p->output;
    w.events = POLLIN;
    w.revents = 0;
    int r;
    do { r = poll(&w, 1, ms); } while (r < 0 && errno == EINTR);
    if (r == 0) return 0;
    if (r < 0) return -1;
    ssize_t n;
    do { n = read(p->output, into, (size_t)size); } while (n < 0 && errno == EINTR);
    return n > 0 ? (int)n : -1;
#endif
}

/* Waits up to `ms` (a negative ms: as long as it takes) for it to end: 1 when it ended, 0 if not yet. */
static int lm_proc_wait(LmProcess* p, int ms) {
    if (p->exited) return 1;
#if defined(_WIN32)
    if (WaitForSingleObject(p->process, ms < 0 ? INFINITE : (DWORD)ms) != WAIT_OBJECT_0) return 0;
    DWORD code = 0;
    GetExitCodeProcess(p->process, &code);
    p->code = (int)code;
    p->exited = 1;
    return 1;
#else
    long long until = lm_proc_now() + ms;
    for (;;) {
        int status = 0;
        pid_t r = waitpid(p->pid, &status, ms < 0 ? 0 : WNOHANG);
        if (r == p->pid) {
            p->code = WIFEXITED(status) ? WEXITSTATUS(status) : 128 + WTERMSIG(status);
            p->exited = 1;
            return 1;
        }
        if (r < 0 && errno != EINTR) { p->exited = 1; p->code = -1; return 1; }
        if (ms >= 0 && lm_proc_now() >= until) return 0;
        if (ms >= 0) {
            struct timespec t = { 0, 5000000 };
            nanosleep(&t, NULL);
        }
    }
#endif
}

static int lm_proc_code(LmProcess* p) { return p->code; }

static void lm_proc_kill(LmProcess* p) {
    if (!p->started || p->exited) return;
#if defined(_WIN32)
    TerminateProcess(p->process, 137);
#else
    kill(p->pid, SIGKILL);
#endif
    lm_proc_wait(p, -1);
}

/* When its memory is freed: killed if it still runs, and everything closed. */
static void lm_proc_free(LmProcess* p) {
    if (!p) return;
    lm_proc_kill(p);
    lm_proc_close_input(p);
#if defined(_WIN32)
    if (p->output) CloseHandle(p->output);
    if (p->process) CloseHandle(p->process);
#else
    if (p->output >= 0) close(p->output);
#endif
    for (int i = 0; i < p->argCount; i++) free(p->args[i]);
    for (int i = 0; i < p->envCount; i++) free(p->env[i]);
    free(p->args);
    free(p->env);
    free(p);
}


